-- =====================================================================
-- EduNexus AI — Consolidated Database Setup Script
-- Includes Schema (Initial, 7-Domains, Integrity) + Complete Seed Data
-- =====================================================================

-- >>> STEP 1: INITIAL SCHEMA >>>
-- =====================================================================
-- EduNexus AI — Student Success & Journey Intelligence Platform
-- Migration: 20261011000001_initial_schema.sql
-- Description: Core Schema Definition with Constraints, Indexes,
--              Row-Level Security (RLS), and Audit Logging Triggers.
-- =====================================================================

-- Enable required PostgreSQL extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =====================================================================
-- 1. User Profiles & Role-Based Access Control (RBAC)
-- =====================================================================

-- Application Role Enum for Educational Staff & Evaluators
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'app_role') THEN
    CREATE TYPE app_role AS ENUM (
      'advisor',        -- Academic advisors managing student journeys
      'counselor',      -- Wellness and attendance counselors
      'faculty',        -- Teachers recording assessments & attendance
      'administrator',  -- Platform admin / institutional lead
      'auditor'         -- Read-only governance & compliance reviewer
    );
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.user_profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL UNIQUE,
  full_name TEXT NOT NULL,
  role app_role NOT NULL DEFAULT 'advisor',
  institution_department TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- 2. Students Master Table
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.students (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id TEXT NOT NULL UNIQUE,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT UNIQUE,
  date_of_birth DATE,
  gender TEXT,
  enrollment_date DATE NOT NULL DEFAULT CURRENT_DATE,
  current_grade TEXT NOT NULL,               -- e.g., 'Grade 10', 'Grade 11'
  academic_term TEXT NOT NULL,               -- e.g., 'AY 2025-26 Term 1'
  section TEXT,                              -- e.g., 'A', 'B', 'C'
  advisor_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'inactive', 'graduated', 'withdrawn', 'suspended', 'on_leave')),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- 3. Attendance Records Table
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.attendance (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  session_date DATE NOT NULL,
  period TEXT NOT NULL DEFAULT 'full_day',
  status TEXT NOT NULL CHECK (status IN ('present', 'absent', 'late', 'excused')),
  remarks TEXT,
  recorded_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_student_date_period UNIQUE (student_id, session_date, period)
);

-- =====================================================================
-- 4. Assessments Table
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.assessments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  subject TEXT NOT NULL,
  assessment_type TEXT NOT NULL
    CHECK (assessment_type IN ('quiz', 'assignment', 'midterm', 'final', 'project', 'lab')),
  term TEXT NOT NULL,                        -- e.g., 'Term 1', 'Term 2'
  assessment_date DATE NOT NULL,
  score NUMERIC(5,2) NOT NULL CHECK (score >= 0),
  max_score NUMERIC(5,2) NOT NULL CHECK (max_score > 0),
  weight_percentage NUMERIC(5,2) CHECK (weight_percentage >= 0 AND weight_percentage <= 100),
  feedback TEXT,
  recorded_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- Critical constraint: score cannot exceed maximum marks
  CONSTRAINT chk_score_within_max CHECK (score <= max_score)
);

-- =====================================================================
-- 5. Engagement Events Table (Extracurricular & LMS signals)
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.engagement_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL
    CHECK (event_type IN ('lms_login', 'library_visit', 'counseling_session', 'extracurricular', 'mentoring', 'peer_study', 'workshop')),
  title TEXT NOT NULL,
  description TEXT,
  duration_minutes INTEGER CHECK (duration_minutes >= 0),
  event_timestamp TIMESTAMPTZ NOT NULL DEFAULT now(),
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- 6. Interventions Table
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.interventions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  intervention_type TEXT NOT NULL
    CHECK (intervention_type IN ('academic_tutoring', 'attendance_counseling', 'behavioral_support', 'parental_engagement', 'peer_mentoring', 'schedule_adjustment', 'wellness_check')),
  priority TEXT NOT NULL DEFAULT 'medium'
    CHECK (priority IN ('low', 'medium', 'high', 'urgent')),
  status TEXT NOT NULL DEFAULT 'planned'
    CHECK (status IN ('planned', 'in_progress', 'completed', 'cancelled', 'under_review')),
  description TEXT NOT NULL,
  goals TEXT,
  assigned_staff_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  assigned_staff_name TEXT,
  start_date DATE NOT NULL DEFAULT CURRENT_DATE,
  target_completion_date DATE,
  actual_completion_date DATE,
  follow_up_date DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_target_date_order CHECK (target_completion_date IS NULL OR target_completion_date >= start_date),
  CONSTRAINT chk_actual_date_order CHECK (actual_completion_date IS NULL OR actual_completion_date >= start_date)
);

-- =====================================================================
-- 7. Intervention Outcomes Table (Before & After Metric Tracking)
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.intervention_outcomes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  intervention_id UUID NOT NULL REFERENCES public.interventions(id) ON DELETE CASCADE,
  metric_name TEXT NOT NULL,                 -- e.g., 'attendance_percentage', 'average_score'
  baseline_value NUMERIC(7,2) NOT NULL,      -- Value prior to intervention
  post_value NUMERIC(7,2),                   -- Measured value post intervention
  target_value NUMERIC(7,2),                 -- Desired threshold
  measurement_date DATE NOT NULL DEFAULT CURRENT_DATE,
  outcome_status TEXT NOT NULL DEFAULT 'evaluating'
    CHECK (outcome_status IN ('improved', 'unchanged', 'declined', 'evaluating')),
  evidence_notes TEXT,
  -- Explicit ethical causation disclaimer stored with every outcome
  causation_disclaimer TEXT NOT NULL DEFAULT
    'Observed change reflects correlation during intervention interval; causal relationship not established without control study.',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- 8. Audit Events Table
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.audit_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type TEXT NOT NULL,                 -- e.g., 'student', 'intervention', 'assessment'
  entity_id UUID NOT NULL,
  action TEXT NOT NULL
    CHECK (action IN ('CREATE', 'UPDATE', 'DELETE', 'VIEW', 'INTERVENTION_STATUS_CHANGE', 'FLAG_REVIEW')),
  performed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  performed_by_name TEXT,
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  ip_address TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- 9. Performance Indexes
-- =====================================================================

CREATE INDEX IF NOT EXISTS idx_students_student_id ON public.students(student_id);
CREATE INDEX IF NOT EXISTS idx_students_status ON public.students(status);
CREATE INDEX IF NOT EXISTS idx_students_grade_section ON public.students(current_grade, section);
CREATE INDEX IF NOT EXISTS idx_attendance_student_date ON public.attendance(student_id, session_date DESC);
CREATE INDEX IF NOT EXISTS idx_attendance_status ON public.attendance(status);
CREATE INDEX IF NOT EXISTS idx_assessments_student_date ON public.assessments(student_id, assessment_date DESC);
CREATE INDEX IF NOT EXISTS idx_assessments_subject ON public.assessments(subject);
CREATE INDEX IF NOT EXISTS idx_engagement_student_time ON public.engagement_events(student_id, event_timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_interventions_student_status ON public.interventions(student_id, status);
CREATE INDEX IF NOT EXISTS idx_interventions_priority ON public.interventions(priority);
CREATE INDEX IF NOT EXISTS idx_interventions_followup ON public.interventions(follow_up_date);
CREATE INDEX IF NOT EXISTS idx_outcomes_intervention ON public.intervention_outcomes(intervention_id);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON public.audit_events(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_created ON public.audit_events(created_at DESC);

-- =====================================================================
-- 10. Automated Timestamp Update Trigger
-- =====================================================================

CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_user_profiles_updated_at ON public.user_profiles;
CREATE TRIGGER trg_user_profiles_updated_at
  BEFORE UPDATE ON public.user_profiles
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS trg_students_updated_at ON public.students;
CREATE TRIGGER trg_students_updated_at
  BEFORE UPDATE ON public.students
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS trg_attendance_updated_at ON public.attendance;
CREATE TRIGGER trg_attendance_updated_at
  BEFORE UPDATE ON public.attendance
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS trg_assessments_updated_at ON public.assessments;
CREATE TRIGGER trg_assessments_updated_at
  BEFORE UPDATE ON public.assessments
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS trg_interventions_updated_at ON public.interventions;
CREATE TRIGGER trg_interventions_updated_at
  BEFORE UPDATE ON public.interventions
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS trg_outcomes_updated_at ON public.intervention_outcomes;
CREATE TRIGGER trg_outcomes_updated_at
  BEFORE UPDATE ON public.intervention_outcomes
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- =====================================================================
-- 11. Row-Level Security (RLS) Configuration
-- =====================================================================

-- Enable RLS strictly on all public tables
ALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.engagement_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interventions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.intervention_outcomes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;

-- Helper Function: Check whether current auth.uid() has an active staff role
CREATE OR REPLACE FUNCTION public.is_authenticated_staff()
RETURNS BOOLEAN AS $$
BEGIN
  -- Returns true if user is logged in and is in public.user_profiles with active status
  RETURN (
    auth.role() = 'authenticated' AND
    EXISTS (
      SELECT 1 FROM public.user_profiles
      WHERE id = auth.uid() AND is_active = true
    )
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Helper Function: Check whether current auth.uid() is an administrator
CREATE OR REPLACE FUNCTION public.is_administrator()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN (
    auth.role() = 'authenticated' AND
    EXISTS (
      SELECT 1 FROM public.user_profiles
      WHERE id = auth.uid() AND role = 'administrator' AND is_active = true
    )
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ---------------------------------------------------------------------
-- RLS Policies: user_profiles
-- ---------------------------------------------------------------------
-- Users can view their own profile; admins can view all profiles
CREATE POLICY "Users can read own profile" ON public.user_profiles
  FOR SELECT TO authenticated
  USING (id = auth.uid() OR public.is_administrator());

CREATE POLICY "Admins can update profiles" ON public.user_profiles
  FOR UPDATE TO authenticated
  USING (public.is_administrator())
  WITH CHECK (public.is_administrator());

-- ---------------------------------------------------------------------
-- RLS Policies: students
-- ---------------------------------------------------------------------
-- Authenticated active staff can view student directory
CREATE POLICY "Staff read students" ON public.students
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

-- Staff can insert/update students (restricted to advisors, faculty, admins)
CREATE POLICY "Staff write students" ON public.students
  FOR INSERT TO authenticated
  WITH CHECK (public.is_authenticated_staff());

CREATE POLICY "Staff update students" ON public.students
  FOR UPDATE TO authenticated
  USING (public.is_authenticated_staff())
  WITH CHECK (public.is_authenticated_staff());

-- ---------------------------------------------------------------------
-- RLS Policies: attendance
-- ---------------------------------------------------------------------
CREATE POLICY "Staff read attendance" ON public.attendance
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

CREATE POLICY "Staff write attendance" ON public.attendance
  FOR INSERT TO authenticated
  WITH CHECK (public.is_authenticated_staff());

CREATE POLICY "Staff update attendance" ON public.attendance
  FOR UPDATE TO authenticated
  USING (public.is_authenticated_staff())
  WITH CHECK (public.is_authenticated_staff());

-- ---------------------------------------------------------------------
-- RLS Policies: assessments
-- ---------------------------------------------------------------------
CREATE POLICY "Staff read assessments" ON public.assessments
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

CREATE POLICY "Staff write assessments" ON public.assessments
  FOR INSERT TO authenticated
  WITH CHECK (public.is_authenticated_staff());

CREATE POLICY "Staff update assessments" ON public.assessments
  FOR UPDATE TO authenticated
  USING (public.is_authenticated_staff())
  WITH CHECK (public.is_authenticated_staff());

-- ---------------------------------------------------------------------
-- RLS Policies: engagement_events
-- ---------------------------------------------------------------------
CREATE POLICY "Staff read engagement" ON public.engagement_events
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

CREATE POLICY "Staff write engagement" ON public.engagement_events
  FOR INSERT TO authenticated
  WITH CHECK (public.is_authenticated_staff());

-- ---------------------------------------------------------------------
-- RLS Policies: interventions & outcomes
-- ---------------------------------------------------------------------
CREATE POLICY "Staff read interventions" ON public.interventions
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

CREATE POLICY "Staff manage interventions" ON public.interventions
  FOR ALL TO authenticated
  USING (public.is_authenticated_staff())
  WITH CHECK (public.is_authenticated_staff());

CREATE POLICY "Staff read outcomes" ON public.intervention_outcomes
  FOR SELECT TO authenticated
  USING (public.is_authenticated_staff());

CREATE POLICY "Staff manage outcomes" ON public.intervention_outcomes
  FOR ALL TO authenticated
  USING (public.is_authenticated_staff())
  WITH CHECK (public.is_authenticated_staff());

-- ---------------------------------------------------------------------
-- RLS Policies: audit_events
-- ---------------------------------------------------------------------
-- Staff can write audit events, only admins & auditors can view audit logs
CREATE POLICY "Staff insert audit events" ON public.audit_events
  FOR INSERT TO authenticated
  WITH CHECK (public.is_authenticated_staff());

CREATE POLICY "Auditors and admins view audit logs" ON public.audit_events
  FOR SELECT TO authenticated
  USING (
    auth.role() = 'authenticated' AND
    EXISTS (
      SELECT 1 FROM public.user_profiles
      WHERE id = auth.uid() AND is_active = true AND role IN ('administrator', 'auditor')
    )
  );

-- NOTICE: Anonymous ('anon') users have zero access to all student records and tables.
-- Backend services connect via service-role key which bypasses RLS for administrative and seed ingestion.


-- >>> STEP 2: KPMG 7-DOMAINS SCHEMA >>>
-- =====================================================================
-- EduNexus AI — KPMG Challenge: Smart Campus Analytics 7-Domain Schema
-- Migration: 20261012000001_kpmg_7domains.sql
-- Description: Extends schema to cover Placement, Skills, Feedback, and
--              LMS telemetry with RLS, audit triggers, and integrity constraints.
-- =====================================================================

-- 1. Placement Readiness Telemetry Table
CREATE TABLE IF NOT EXISTS public.placement_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  aptitude_score NUMERIC(5, 2) NOT NULL CHECK (aptitude_score >= 0 AND aptitude_score <= 100),
  coding_score NUMERIC(5, 2) NOT NULL CHECK (coding_score >= 0 AND coding_score <= 100),
  mock_interview_score NUMERIC(5, 2) NOT NULL CHECK (mock_interview_score >= 0 AND mock_interview_score <= 100),
  resume_score NUMERIC(5, 2) DEFAULT 75.0 CHECK (resume_score >= 0 AND resume_score <= 100),
  readiness_tier TEXT NOT NULL DEFAULT 'developing'
    CHECK (readiness_tier IN ('not_ready', 'developing', 'placement_ready', 'advanced_hire')),
  mock_interviews_attended INT NOT NULL DEFAULT 1 CHECK (mock_interviews_attended >= 0),
  evaluated_at DATE NOT NULL DEFAULT CURRENT_DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_placement_student_id ON public.placement_records(student_id);
CREATE INDEX IF NOT EXISTS idx_placement_evaluated_at ON public.placement_records(evaluated_at);

-- 2. Student Skills & Competencies Table
CREATE TABLE IF NOT EXISTS public.skills_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  technical_score NUMERIC(5, 2) NOT NULL CHECK (technical_score >= 0 AND technical_score <= 100),
  soft_skills_score NUMERIC(5, 2) NOT NULL CHECK (soft_skills_score >= 0 AND soft_skills_score <= 100),
  certifications_count INT NOT NULL DEFAULT 0 CHECK (certifications_count >= 0),
  verified_skills JSONB NOT NULL DEFAULT '[]'::jsonb,
  last_assessed_date DATE NOT NULL DEFAULT CURRENT_DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_skills_student_id ON public.skills_records(student_id);

-- 3. Feedback & Sentiment Evaluations Table
CREATE TABLE IF NOT EXISTS public.feedback_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  faculty_sentiment NUMERIC(5, 2) NOT NULL CHECK (faculty_sentiment >= 0 AND faculty_sentiment <= 100),
  student_satisfaction NUMERIC(5, 2) NOT NULL CHECK (student_satisfaction >= 0 AND student_satisfaction <= 100),
  mentor_notes TEXT,
  academic_term TEXT NOT NULL,
  recorded_at DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_feedback_student_id ON public.feedback_records(student_id);

-- 4. LMS Activity & Digital Learning Telemetry Table
CREATE TABLE IF NOT EXISTS public.lms_activity_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
  weekly_login_count INT NOT NULL DEFAULT 0 CHECK (weekly_login_count >= 0),
  module_completion_pct NUMERIC(5, 2) NOT NULL CHECK (module_completion_pct >= 0 AND module_completion_pct <= 100),
  assignments_submitted_pct NUMERIC(5, 2) NOT NULL CHECK (assignments_submitted_pct >= 0 AND assignments_submitted_pct <= 100),
  forum_posts_count INT NOT NULL DEFAULT 0 CHECK (forum_posts_count >= 0),
  last_login_date DATE,
  recorded_at DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_lms_student_id ON public.lms_activity_records(student_id);

-- =====================================================================
-- 5. Row-Level Security (RLS) Policies
-- =====================================================================

ALTER TABLE public.placement_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.skills_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feedback_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lms_activity_records ENABLE ROW LEVEL SECURITY;

-- Read policies for authenticated staff
CREATE POLICY "Authenticated staff can view placement records"
  ON public.placement_records FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated staff can manage placement records"
  ON public.placement_records FOR ALL TO authenticated USING (true);

CREATE POLICY "Authenticated staff can view skills records"
  ON public.skills_records FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated staff can manage skills records"
  ON public.skills_records FOR ALL TO authenticated USING (true);

CREATE POLICY "Authenticated staff can view feedback records"
  ON public.feedback_records FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated staff can manage feedback records"
  ON public.feedback_records FOR ALL TO authenticated USING (true);

CREATE POLICY "Authenticated staff can view lms records"
  ON public.lms_activity_records FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated staff can manage lms records"
  ON public.lms_activity_records FOR ALL TO authenticated USING (true);


-- >>> STEP 3: INTEGRITY & AUTHORIZATION >>>
-- Canonical API schema, restricted staff permissions, and atomic audited writes.
-- Apply after the initial and seven-domain migrations. Never run demo reset against SQL.
BEGIN;
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS department text;
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS cgpa numeric(4,2) CHECK (cgpa BETWEEN 0 AND 10);
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS backlogs integer CHECK (backlogs >= 0);
CREATE INDEX IF NOT EXISTS idx_students_department ON public.students(department);
ALTER TABLE public.placement_records ALTER COLUMN resume_score DROP DEFAULT;
ALTER TABLE public.placement_records ALTER COLUMN readiness_tier DROP DEFAULT;
ALTER TABLE public.placement_records ALTER COLUMN readiness_tier DROP NOT NULL;
ALTER TABLE public.placement_records ALTER COLUMN mock_interviews_attended DROP DEFAULT;
ALTER TABLE public.placement_records ALTER COLUMN mock_interviews_attended DROP NOT NULL;
ALTER TABLE public.skills_records ALTER COLUMN certifications_count DROP DEFAULT;
ALTER TABLE public.skills_records ALTER COLUMN certifications_count DROP NOT NULL;
ALTER TABLE public.lms_activity_records ALTER COLUMN weekly_login_count DROP DEFAULT;
ALTER TABLE public.lms_activity_records ALTER COLUMN weekly_login_count DROP NOT NULL;
ALTER TABLE public.lms_activity_records ALTER COLUMN forum_posts_count DROP DEFAULT;
ALTER TABLE public.lms_activity_records ALTER COLUMN forum_posts_count DROP NOT NULL;
ALTER TABLE public.interventions ADD CONSTRAINT chk_followup_date_order
  CHECK (follow_up_date IS NULL OR follow_up_date >= start_date) NOT VALID;

CREATE TABLE public.risk_overrides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id uuid NOT NULL UNIQUE REFERENCES public.students(id) ON DELETE CASCADE,
  is_overridden boolean NOT NULL DEFAULT false,
  original_tier text NOT NULL CHECK (original_tier IN ('low','moderate','high','critical','insufficient_data')),
  override_tier text CHECK (override_tier IN ('low','moderate','high','critical')),
  override_reason text,
  reviewed_by text,
  reviewed_at timestamptz,
  CHECK (NOT is_overridden OR (override_tier IS NOT NULL AND length(trim(override_reason)) >= 5))
);
ALTER TABLE public.risk_overrides ENABLE ROW LEVEL SECURITY;

-- Both JWT roles and profile activity must agree. app_metadata is server managed.
CREATE OR REPLACE FUNCTION public.is_authenticated_staff() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT auth.role() = 'authenticated'
    AND auth.jwt()->'app_metadata'->>'role' IN ('administrator','admin','advisor','counselor','faculty','staff')
    AND EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active
      AND role IN ('administrator','advisor','counselor','faculty'));
$$;
CREATE OR REPLACE FUNCTION public.can_read_student_data() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT public.is_authenticated_staff() OR (
    auth.role() = 'authenticated' AND auth.jwt()->'app_metadata'->>'role' = 'auditor'
    AND EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active AND role = 'auditor'));
$$;
CREATE OR REPLACE FUNCTION public.is_administrator() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT auth.role() = 'authenticated' AND auth.jwt()->'app_metadata'->>'role' IN ('admin','administrator')
    AND EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active AND role = 'administrator');
$$;
ALTER FUNCTION public.handle_updated_at() SET search_path = public, pg_temp;

DO $$
DECLARE t text; p record;
BEGIN
  FOREACH t IN ARRAY ARRAY['students','attendance','assessments','engagement_events',
    'placement_records','skills_records','feedback_records','lms_activity_records',
    'interventions','intervention_outcomes','risk_overrides'] LOOP
    FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP
      EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, t);
    END LOOP;
    EXECUTE format('CREATE POLICY staff_read ON public.%I FOR SELECT TO authenticated USING (public.can_read_student_data())',t);
    -- Mutations go through the backend transaction so their audit cannot be omitted.
    -- No direct authenticated write policy is granted.
  END LOOP;
END $$;
DROP POLICY IF EXISTS "Staff insert audit events" ON public.audit_events;

-- Service-role-only RPC. Dynamic identifiers are allowlisted and quoted.
-- jsonb_populate_record preserves canonical SQL type checks, FKs, and constraints.
CREATE OR REPLACE FUNCTION public.edunexus_commit(
  p_table text, p_records jsonb, p_audits jsonb, p_delete_ids uuid[] DEFAULT ARRAY[]::uuid[]
) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $$
DECLARE cols text; updates text;
BEGIN
  IF p_table NOT IN ('students','attendance','assessments','engagement_events',
    'placement_records','skills_records','feedback_records','lms_activity_records',
    'interventions','intervention_outcomes','risk_overrides') THEN
    RAISE EXCEPTION 'Unsupported table';
  END IF;
  IF jsonb_typeof(p_records) <> 'array' OR jsonb_typeof(p_audits) <> 'array' THEN
    RAISE EXCEPTION 'Expected record arrays';
  END IF;
  IF jsonb_array_length(p_audits) <> jsonb_array_length(p_records) + cardinality(p_delete_ids) THEN
    RAISE EXCEPTION 'An audit event is required for every mutation';
  END IF;
  -- Serialize concurrent writes from this application, including CSV batches.
  PERFORM pg_advisory_xact_lock(hashtext('edunexus_commit'));
  SELECT string_agg(format('%I',column_name), ',' ORDER BY ordinal_position),
    string_agg(format('%I=EXCLUDED.%I',column_name,column_name), ',' ORDER BY ordinal_position)
      FILTER (WHERE column_name <> 'id')
    INTO cols, updates FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table;
  EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_recordset(NULL::public.%I,$1) ON CONFLICT (id) DO UPDATE SET %s',
    p_table,cols,cols,p_table,updates) USING p_records;
  EXECUTE format('DELETE FROM public.%I WHERE id=ANY($1)',p_table) USING p_delete_ids;
END;
$$;
REVOKE ALL ON FUNCTION public.edunexus_commit(text,jsonb,jsonb,uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.edunexus_commit(text,jsonb,jsonb,uuid[]) TO service_role;
COMMIT;


